tool_input.newString:
@staticmethod
    def _budget(vram_gb: float) -> Tuple[int, int]:
        """VRAM-aware ctx/slots budget (fallback when no ctx-catalog entry)."""
        if vram_gb >= 24.0:
            return 16384, 4
        if vram_gb >= 10.0:
            return 4096, 2
        return 2048, 1

    # -- offer side: ctx-catalog (orchestrator-decided windows) ----------

    def catalog_ctx(self, model: Optional[str] = None) -> Optional[int]:
        """Context window from the orchestrator ctx-catalog (empirically
        validated). If `model` matches a catalog entry name (substring),
        return that entry's ctx; otherwise return the uniform shared ctx
        (all entries equal) or None when the catalog is empty/unusable.
        """
        models = self.catalog.get("models") or []
        ctxs: List[int] = []
        for m in models:
            if not isinstance(m, dict):
                continue
            if model and str(m.get("model", "")).find(model) == -1:
                continue
            try:
                ctxs.append(int(m.get("ctx") or 0))
            except (TypeError, ValueError):
                continue
        if not ctxs:
            return None
        if len(set(ctxs)) == 1:
            return ctxs[0]
        return max(ctxs)

    def budget(self, vram_gb: float,
               model: Optional[str] = None) -> Tuple[int, int]:
        """ctx/slots budget: ctx-catalog first, VRAM fallback otherwise."""
        ctx = self.catalog_ctx(model)
        if ctx:
            slots = 4 if vram_gb >= 24.0 else (2 if vram_gb >= 10.0 else 1)
            return ctx, slots
        return self._budget(vram_gb)

